/* eslint-disable stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setNonEnumerableReadOnlyProperty = require( '@stdlib/utils/define-nonenumerable-read-only-property' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var EncodingSet = require( '@stdlib/plot/vega/mark/base/encoding-set' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAngle = require( './angle/get.js' );
var setAngle = require( './angle/set.js' );

var getPath = require( './path/get.js' );
var setPath = require( './path/set.js' );

var getProperties = require( './properties/get.js' );

var getScaleX = require( './scale-x/get.js' );
var setScaleX = require( './scale-x/set.js' );

var getScaleY = require( './scale-y/get.js' );
var setScaleY = require( './scale-y/set.js' );


// VARIABLES //

var debug = logger( 'vega:mark:path:encoding-set:main' );


// MAIN //

/**
* Path mark encoding set constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {Value} [options.angle] - rotation angle in degrees
* @param {Value} [options.aria] - flag indicating whether to include ARIA attributes in SVG output
* @param {Value} [options.blend] - color blend mode
* @param {Value} [options.cursor] - mouse cursor used over a mark
* @param {Value} [options.description] - text description of a mark item for ARIA accessibility
* @param {Value} [options.fill] - fill color
* @param {Value} [options.fillOpacity] - fill opacity
* @param {Value} [options.href] - URL to load upon mouse click
* @param {Value} [options.opacity] - mark opacity
* @param {Value} [options.path] - SVG path string
* @param {Value} [options.scaleX] - horizontal scale factor
* @param {Value} [options.scaleY] - vertical scale factor
* @param {Value} [options.stroke] - stroke color
* @param {Value} [options.strokeCap] - stroke cap for line ending style
* @param {Value} [options.strokeDash] - stroke dash
* @param {Value} [options.strokeDashOffset] - pixel offset at which to start the dash array
* @param {Value} [options.strokeJoin] - stroke line join method
* @param {Value} [options.strokeMiterLimit] - miter limit at which to bevel a line join
* @param {Value} [options.strokeOpacity] - stroke opacity
* @param {Value} [options.strokeWidth] - stroke width
* @param {Value} [options.tooltip] - tooltip text to show upon mouse hover
* @param {Value} [options.x] - primary x-coordinate
* @param {Value} [options.y] - primary y-coordinate
* @param {Value} [options.zindex] - layering order of sibling mark items
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {PathEncodingSet} encoding set instance
*
* @example
* var encoding = new PathEncodingSet();
* // returns <PathEncodingSet>
*/
function PathEncodingSet( options ) {
	var nargs;
	var v;
	var k;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof PathEncodingSet ) ) {
		if ( nargs === 0 ) {
			return new PathEncodingSet();
		}
		return new PathEncodingSet( options );
	}
	EncodingSet.call( this );
	if ( nargs ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		// Validate provided options by attempting to assign option values to corresponding fields...
		for ( i = 0; i < properties.length; i++ ) {
			k = properties[ i ];
			if ( !hasProp( options, k ) ) {
				continue;
			}
			v = options[ k ];
			try {
				this[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error. Error: %s', err.message );

				// FIXME: retain thrown error type
				throw new Error( transformErrorMessage( err.message ) );
			}
		}
	}
	return this;
}

/*
* Inherit from the `EncodingSet` prototype.
*/
inherit( PathEncodingSet, EncodingSet );

/**
* Constructor name.
*
* @private
* @name name
* @memberof PathEncodingSet
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( PathEncodingSet, 'name', 'PathEncodingSet' );

/**
* Encoding specifying a rotation angle (in degrees).
*
* @name angle
* @memberof PathEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new PathEncodingSet({
*     'angle': new Value({
*         'value': 45
*     })
* });
*
* var v = encoding.angle;
* // returns <Value>
*/
setReadWriteAccessor( PathEncodingSet.prototype, 'angle', getAngle, setAngle );

/**
* Encoding specifying a mark height (in pixels).
*
* ## Notes
*
* -   This property is inherited from the parent prototype and is not applicable to path mark types.
*
* @name height
* @memberof PathEncodingSet.prototype
* @readonly
* @type {void}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new PathEncodingSet();
*
* var v = encoding.height;
* // returns undefined
*/
setNonEnumerableReadOnlyProperty( PathEncodingSet.prototype, 'height', void 0 );

/**
* Encoding specifying an SVG path string describing the geometry of the path.
*
* @name path
* @memberof PathEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new PathEncodingSet({
*     'path': new Value({
*         'value': 'M-50,-50 L50,50 V-50 L-50,50 Z'
*     })
* });
*
* var v = encoding.path;
* // returns <Value>
*/
setReadWriteAccessor( PathEncodingSet.prototype, 'path', getPath, setPath );

/**
* EncodingSet properties.
*
* @name properties
* @memberof PathEncodingSet.prototype
* @type {Array<string>}
*
* @example
* var encoding = new PathEncodingSet();
*
* var v = encoding.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( PathEncodingSet.prototype, 'properties', getProperties );

/**
* Encoding specifying a horizontal scale factor.
*
* @name scaleX
* @memberof PathEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new PathEncodingSet({
*     'scaleX': new Value({
*         'value': 2
*     })
* });
*
* var v = encoding.scaleX;
* // returns <Value>
*/
setReadWriteAccessor( PathEncodingSet.prototype, 'scaleX', getScaleX, setScaleX );

/**
* Encoding specifying a vertical scale factor.
*
* @name scaleY
* @memberof PathEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new PathEncodingSet({
*     'scaleY': new Value({
*         'value': 2
*     })
* });
*
* var v = encoding.scaleY;
* // returns <Value>
*/
setReadWriteAccessor( PathEncodingSet.prototype, 'scaleY', getScaleY, setScaleY );

/**
* Encoding specifying a mark width (in pixels).
*
* ## Notes
*
* -   This property is inherited from the parent prototype and is not applicable to path mark types.
*
* @name width
* @memberof PathEncodingSet.prototype
* @readonly
* @type {void}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new PathEncodingSet();
*
* var v = encoding.width;
* // returns undefined
*/
setNonEnumerableReadOnlyProperty( PathEncodingSet.prototype, 'width', void 0 );

/**
* Encoding specifying a mark secondary x-coordinate (in pixels).
*
* ## Notes
*
* -   This property is inherited from the parent prototype and is not applicable to path mark types.
*
* @name x2
* @memberof PathEncodingSet.prototype
* @readonly
* @type {void}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new PathEncodingSet();
*
* var v = encoding.x2;
* // returns undefined
*/
setNonEnumerableReadOnlyProperty( PathEncodingSet.prototype, 'x2', void 0 );

/**
* Encoding specifying a mark center x-coordinate (in pixels).
*
* ## Notes
*
* -   This property is inherited from the parent prototype and is not applicable to path mark types.
*
* @name xc
* @memberof PathEncodingSet.prototype
* @readonly
* @type {void}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new PathEncodingSet();
*
* var v = encoding.xc;
* // returns undefined
*/
setNonEnumerableReadOnlyProperty( PathEncodingSet.prototype, 'xc', void 0 );

/**
* Encoding specifying a mark secondary y-coordinate (in pixels).
*
* ## Notes
*
* -   This property is inherited from the parent prototype and is not applicable to path mark types.
*
* @name y2
* @memberof PathEncodingSet.prototype
* @readonly
* @type {void}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new PathEncodingSet();
*
* var v = encoding.y2;
* // returns undefined
*/
setNonEnumerableReadOnlyProperty( PathEncodingSet.prototype, 'y2', void 0 );

/**
* Encoding specifying a mark center y-coordinate (in pixels).
*
* ## Notes
*
* -   This property is inherited from the parent prototype and is not applicable to path mark types.
*
* @name yc
* @memberof PathEncodingSet.prototype
* @readonly
* @type {void}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new PathEncodingSet();
*
* var v = encoding.yc;
* // returns undefined
*/
setNonEnumerableReadOnlyProperty( PathEncodingSet.prototype, 'yc', void 0 );


// EXPORTS //

module.exports = PathEncodingSet;
